/**
 * Ports reference/AteAnne_Expected_Calculations.json (generated by the
 * supplied Python reference) into TypeScript assertions against the real
 * domain classes used by the app.
 */
import { describe, expect, it } from "vitest";
import fixtures from "../../reference/AteAnne_Expected_Calculations.json";
import { LargestRemainderAllocator } from "@/domain/allocation/LargestRemainderAllocator";
import { Fraction } from "@/domain/money/Fraction";
import { ReceiptCalculator } from "@/domain/receipt/ReceiptCalculator";
import { ReceiptReconciler } from "@/domain/receipt/ReceiptReconciler";
import { EventLedger } from "@/domain/event/EventLedger";
import { SettlementPlanner } from "@/domain/settlement/SettlementPlanner";
import { LedgerReport, PaymentLedger } from "@/domain/payments/PaymentLedger";
import type { LineInput, MemberReceiptShare, ReceiptInput } from "@/domain/receipt/types";

const alloc = new LargestRemainderAllocator();
const toNum = (m: Map<string, bigint>) => Object.fromEntries([...m].map(([k, v]) => [k, Number(v)]));
const toBig = (o: Record<string, number>) => Object.entries(o).map(([k, v]) => [k, BigInt(v)] as const);

describe("synthetic_centavo_rounding", () => {
  const f = fixtures.synthetic_centavo_rounding;
  it("PHP1.00 over three → 34/33/33", () => {
    expect(toNum(alloc.allocate(100n, [{ key: "p01", weight: 1 }, { key: "p02", weight: 1 }, { key: "p03", weight: 1 }]))).toEqual(f.one_peso_by_three);
  });
  it("1 centavo over three → 1/0/0", () => {
    expect(toNum(alloc.allocate(1n, [{ key: "p01", weight: 1 }, { key: "p02", weight: 1 }, { key: "p03", weight: 1 }]))).toEqual(f.one_centavo_by_three);
  });
  it("rational weights 1/2, 1/3, 1/6 of 101", () => {
    const r = alloc.allocate(101n, [
      { key: "p01", weight: new Fraction(1n, 2n) },
      { key: "p02", weight: new Fraction(1n, 3n) },
      { key: "p03", weight: new Fraction(1n, 6n) },
    ]);
    expect(toNum(r)).toEqual(f.rational_weights_101_centavos);
  });
  it("zero weight excluded", () => {
    expect(toNum(alloc.allocate(101n, [{ key: "p01", weight: 1 }, { key: "p02", weight: 0 }, { key: "p03", weight: 1 }]))).toEqual(f.zero_weight_excluded);
  });
  it("large exact integer reference beyond Number.MAX_SAFE_INTEGER", () => {
    const r = alloc.allocate(9007199254740991n, [{ key: "p01", weight: 1 }, { key: "p02", weight: 1 }, { key: "p03", weight: 1 }]);
    expect(Object.fromEntries([...r].map(([k, v]) => [k, v.toString()]))).toEqual(
      Object.fromEntries(Object.entries(f.large_exact_integer_reference_not_app_input_limit).map(([k, v]) => [k, BigInt(v as number).toString()])),
    );
  });
});

describe("synthetic_rejections", () => {
  const msg = Object.fromEntries(fixtures.synthetic_rejections.map((r) => [r.case, r.error]));
  it("positive charge zero basis", () => {
    expect(() => alloc.allocate(1n, [{ key: "p01", weight: 0 }, { key: "p02", weight: 0 }])).toThrow(msg.positive_charge_zero_basis);
  });
  it("negative money", () => {
    expect(() => alloc.allocate(-1n, [{ key: "p01", weight: 1 }])).toThrow(msg.negative_money);
  });
  it("float weight", () => {
    expect(() => alloc.allocate(100n, [{ key: "p01", weight: 0.5 }])).toThrow(msg.float_weight);
  });
  const original = { recipientId: "p01", status: "VERIFIED" as const, reversed: false };
  it("reversal after done", () => {
    expect(() => PaymentLedger.assertCanReverse(original, "p01", true, "mistake")).toThrow(msg.reversal_after_done);
  });
  it("reversal by wrong actor", () => {
    expect(() => PaymentLedger.assertCanReverse(original, "p03", false, "mistake")).toThrow(msg.reversal_wrong_actor);
  });
  it("duplicate reversal", () => {
    expect(() => PaymentLedger.assertCanReverse({ ...original, reversed: true }, "p01", false, "mistake")).toThrow(msg.duplicate_reversal);
  });
});

describe("pictured_receipt_reconciliation (visible totals only)", () => {
  const p = fixtures.pictured_receipt_reconciliation;
  it("normalised ex-VAT discount reconciles without double counting VAT or the card line", () => {
    expect(p.price_excluding_vat_centavos - p.printed_loyalty_discount_ex_vat_centavos).toBe(p.net_ex_vat_centavos);
    expect(p.net_ex_vat_centavos + p.included_vat_centavos).toBe(p.net_items_including_vat_centavos);
    expect(p.gross_items_centavos - p.effective_discount_on_gross_including_vat_centavos).toBe(p.net_items_including_vat_centavos);
    // Entered in the app as: one gross line, one explicit equivalent gross discount, the printed service amount.
    const receipt: ReceiptInput = {
      id: "pictured",
      label: "Restaurant (totals only)",
      payerId: "x",
      payable: BigInt(p.total_due_centavos),
      lines: [{ id: "items", position: 0, label: "Gross items (VAT-inclusive)", quantity: 1, amount: BigInt(p.gross_items_centavos), mode: "SHARED", claims: [] }],
      adjustments: [
        { id: "disc", position: 0, kind: "DISCOUNT", label: "Loyalty (gross-equivalent)", amount: BigInt(p.effective_discount_on_gross_including_vat_centavos), eligibleLineIds: "ALL" },
        { id: "svc", position: 1, kind: "SERVICE", label: "Service charge (printed)", amount: BigInt(p.service_charge_centavos), eligibleLineIds: "ALL" },
      ],
    };
    const r = new ReceiptReconciler().reconcile(receipt);
    expect(r.reconciled).toBe(true);
    expect(r.computedPayable).toBe(404670n);
    expect(p.participants).toBeNull();
    expect(p.claimed_allocations).toBeNull();
  });
});

function dinnerReceipt(): { receipt: ReceiptInput; ids: string[] } {
  const d = fixtures.synthetic_nine_person_dinner;
  const ids = Object.keys(d.participants);
  const lines: LineInput[] = [
    { id: "shared", position: 0, label: "Shared dishes", quantity: 1, amount: 180000n, mode: "SHARED", claims: ids.map((m) => ({ memberId: m, units: 1 })) },
    { id: "rice", position: 1, label: "Rice", quantity: 3, amount: 18000n, mode: "SHARED", claims: ids.filter((m) => m !== "p02").map((m) => ({ memberId: m, units: 1 })) },
    ...ids.map((m, i) => ({
      id: `solo-${m}`,
      position: 2 + i,
      label: `Solo meal ${d.participants[m as keyof typeof d.participants]}`,
      quantity: 1,
      amount: BigInt(d.receipt.solo_meals_centavos[m as keyof typeof d.receipt.solo_meals_centavos]),
      mode: "UNITS" as const,
      claims: [{ memberId: m, units: 1 }],
    })),
  ];
  return {
    ids,
    receipt: {
      id: "dinner-r1",
      label: "Dinner",
      payerId: "p01",
      payable: BigInt(d.receipt.total_due_centavos),
      lines,
      adjustments: [{ id: "svc", position: 0, kind: "SERVICE", label: "Service", amount: 47800n, eligibleLineIds: "ALL" }],
    },
  };
}

describe("synthetic_nine_person_dinner (Mark paid; Juan skipped rice)", () => {
  const d = fixtures.synthetic_nine_person_dinner;
  it("matches every per-person figure", () => {
    const { receipt, ids } = dinnerReceipt();
    const calc = new ReceiptCalculator().calculate(receipt, ids);
    expect(calc.ok).toBe(true);
    if (!calc.ok) return;
    for (const id of ids) {
      const s = calc.shares.get(id)!;
      const exp = d.allocation_centavos[id as keyof typeof d.allocation_centavos];
      expect(Number(s.lineShares.get("shared"))).toBe(exp.shared_dishes);
      expect(Number(s.lineShares.get("rice") ?? 0n)).toBe(exp.rice);
      expect(Number(s.itemsGross)).toBe(exp.base);
      expect(Number(s.chargeTotal)).toBe(exp.service);
      expect(Number(s.total)).toBe(exp.owed);
    }
  });
  it("nets and transfers match", () => {
    const { receipt, ids } = dinnerReceipt();
    const result = new EventLedger().calculate([receipt], ids);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    for (const p of result.positions) {
      expect(Number(p.net)).toBe(d.allocation_centavos[p.memberId as keyof typeof d.allocation_centavos].net_receive_positive_send_negative);
    }
    expect(result.edges.map((e) => ({ from: e.from, to: e.to, amount_centavos: Number(e.amount) }))).toEqual(d.settlement_transfers);
    expect(result.positions.reduce((a, p) => a + p.net, 0n)).toBe(0n);
  });
  it("Juan has zero rice and no rice-linked service", () => {
    const { receipt, ids } = dinnerReceipt();
    const calc = new ReceiptCalculator().calculate(receipt, ids);
    if (!calc.ok) throw new Error("calc failed");
    const juan = calc.shares.get("p02")!;
    expect(juan.lineShares.has("rice")).toBe(false);
    expect(juan.chargeTotal).toBe(4500n); // 478 × 450 / 4780
  });
});

describe("synthetic_scoped_discount", () => {
  const s = fixtures.synthetic_scoped_discount;
  it("discount applies only to eligible lines; service on post-discount base", () => {
    const receipt: ReceiptInput = {
      id: "scoped",
      label: "Scoped",
      payerId: "p01",
      payable: BigInt(s.total_centavos),
      lines: [
        { id: "a", position: 0, label: "A", quantity: 1, amount: 10000n, mode: "SHARED", claims: [{ memberId: "p01", units: 1 }] },
        { id: "b", position: 1, label: "B", quantity: 1, amount: 20000n, mode: "SHARED", claims: [{ memberId: "p02", units: 1 }] },
        { id: "c", position: 2, label: "C", quantity: 1, amount: 30000n, mode: "SHARED", claims: [{ memberId: "p03", units: 1 }] },
      ],
      adjustments: [
        { id: "d", position: 0, kind: "DISCOUNT", label: "Promo", amount: 3000n, eligibleLineIds: ["a", "b"] },
        { id: "svc", position: 1, kind: "SERVICE", label: "Service", amount: 5700n, eligibleLineIds: "ALL" },
      ],
    };
    const calc = new ReceiptCalculator().calculate(receipt, ["p01", "p02", "p03"]);
    if (!calc.ok) throw new Error(JSON.stringify(calc.issues));
    const shares = calc.shares;
    const pick = (f: (x: MemberReceiptShare) => bigint) =>
      Object.fromEntries(["p01", "p02", "p03"].map((id) => [id, Number(f(shares.get(id)!))]));
    expect(pick((x) => x.discountTotal)).toEqual(s.discount_allocations_centavos);
    expect(pick((x) => x.itemsGross - x.discountTotal)).toEqual(s.post_discount_item_shares_centavos);
    expect(pick((x) => x.chargeTotal)).toEqual(s.service_allocations_centavos);
    expect(pick((x) => x.total)).toEqual(s.final_owed_centavos);
  });
});

describe("synthetic_multiple_receipts", () => {
  const m = fixtures.synthetic_multiple_receipts;
  it("nets and deterministic transfers match", () => {
    const ids = Object.keys(m.participants);
    // Build each receipt as one units line per consumer so owed amounts match exactly.
    const receipts: ReceiptInput[] = m.receipts.map((r) => {
      const payer = Object.entries(r.paid_centavos).find(([, v]) => v > 0)![0];
      return {
        id: r.id,
        label: r.id,
        payerId: payer,
        payable: BigInt(r.total_centavos),
        adjustments: [],
        lines: Object.entries(r.owed_centavos)
          .filter(([, v]) => v > 0)
          .map(([who, v], i) => ({ id: `${r.id}-${who}`, position: i, label: who, quantity: 1, amount: BigInt(v), mode: "SHARED" as const, claims: [{ memberId: who, units: 1 }] })),
      };
    });
    const result = new EventLedger().calculate(receipts, ids);
    if (!result.ok) throw new Error("calc failed");
    expect(Object.fromEntries(result.positions.map((p) => [p.memberId, Number(p.net)]))).toEqual(m.net_receive_positive_send_negative_centavos);
    expect(Object.fromEntries(result.positions.map((p) => [p.memberId, Number(p.funding)]))).toEqual(m.total_paid_centavos);
    expect(Object.fromEntries(result.positions.map((p) => [p.memberId, Number(p.cost)]))).toEqual(m.total_owed_centavos);
    expect(result.edges.map((e) => ({ from: e.from, to: e.to, amount_centavos: Number(e.amount) }))).toEqual(m.settlement_transfers);
  });
});

describe("synthetic_payment_workflow timeline", () => {
  const m = fixtures.synthetic_multiple_receipts;
  const wf = fixtures.synthetic_payment_workflow;
  it("replays reported/rejected/verified/reversal effects exactly", () => {
    const initial = new Map(toBig(m.net_receive_positive_send_negative_centavos));
    const edges = new SettlementPlanner()
      .plan([...initial])
      .map((e) => ({ id: `${e.from}->${e.to}`, ...e }));
    const reports = new Map<string, LedgerReport>();
    for (const step of wf.timeline) {
      const r = step.report as { id: string; from: string; to: string; amount_centavos: number; status: string; original_payment_id?: string };
      const edgeId = `${r.from}->${r.to}`;
      if (r.status === "verification_reversal") {
        const orig = reports.get(r.original_payment_id!)!;
        PaymentLedger.assertCanReverse({ recipientId: r.to, status: orig.status, reversed: orig.reversed }, "p01", false, "confirmed in error");
        orig.reversed = true;
      } else if (r.status === "reported") {
        new PaymentLedger(edges, [...reports.values()]).assertCanReport(edgeId, r.from, BigInt(r.amount_centavos));
        reports.set(r.id, { id: r.id, edgeId, amount: BigInt(r.amount_centavos), status: "REPORTED", reversed: false });
      } else {
        const rep = reports.get(r.id)!;
        PaymentLedger.assertCanDecide({ recipientId: r.to, status: rep.status }, r.to);
        rep.status = r.status === "verified" ? "VERIFIED" : "REJECTED";
      }
      const ledger = new PaymentLedger(edges, [...reports.values()]);
      expect(Object.fromEntries([...ledger.remainingNets(initial)].map(([k, v]) => [k, Number(v)]))).toEqual(step.verified_remaining_balances_centavos);
    }
    expect(new PaymentLedger(edges, [...reports.values()]).completionBlockers()).toEqual([]);
  });
});
